-- database_export.sql (real BODS data -- Stagecoach Cumbria & North Lancashire, no synthetic)
CREATE TABLE IF NOT EXISTS routes (line_ref TEXT PRIMARY KEY, route_name TEXT, scheduled_headway_sec REAL);
CREATE TABLE IF NOT EXISTS bunching_events (line_ref TEXT, vehicle_ref TEXT, recorded_at_time TEXT, observed_headway_sec REAL, scheduled_headway_sec REAL, headway_ratio REAL, is_bunching INTEGER);
